template.script:
(function () {
  var btn = document.querySelector('[data-nv-copiar]');
  if (!btn) { return; }
  var out = btn.parentNode.parentNode.querySelector('.nv-share__ok');
  btn.hidden = false;
  function done(ok) { out.textContent = ok ? 'Link copiado.' : 'No se pudo copiar: mantené apretado el link para copiarlo.'; }
  function fallback(text) {
    var area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.opacity = '0';
    document.body.appendChild(area);
    area.select();
    var ok = false;
    try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    document.body.removeChild(area);
    done(ok);
  }
  btn.addEventListener('click', function () {
    var text = btn.getAttribute('data-nv-copiar');
    if (navigator.clipboard) {
      if (window.isSecureContext) {
        navigator.clipboard.writeText(text).then(function () { done(true); }, function () { fallback(text); });
        return;
      }
    }
    fallback(text);
  });
})();
